set-variable.value:
#[%dw 2.0
output text/plain
---
write({
	"Audit": {
		"Canal": vars.headers.name
	},
	"Filter": {
		"Zone": vars.variablesRequest.zone,
		"Stratum": (vars.variablesRequest.stratum as Number),
		"Technology": vars.variablesRequest.technology,
		"Order_Type": vars.variablesRequest.orderType,
		"UEN": vars.variablesRequest.uen
	} filterObject ((value, key) -> value != null)
},
"application/json"
)]

java:invoke-static.java:args:
#[{
	text: payload.WSResponseBody,
	ivBase64: vars.x_civ_response,
	secret: vars.secret.secret
}]

set-variable.value:
#[%dw 2.0
output text/plain
---
write({
	"Audit": {
		"Canal": vars.headers.name
	},
	"Filter": {
		"Bundle_type": vars.variablesRequest.bundletype,
		"Zone": vars.variablesRequest.zone,
		"Stratum": if (vars.variablesRequest.stratum != null) 
                 (vars.variablesRequest.stratum as Number) 
               else 
                 null,
		"Technology": vars.variablesRequest.technology,
		"Order_Type": vars.variablesRequest.orderType,
		"UEN": vars.variablesRequest.uen
	} filterObject ((value, key) -> value != null)
},
"application/json"
)]

java:invoke-static.java:args:
#[{
	text: payload.WSResponseBody,
	ivBase64: vars.x_civ_response,
	secret: vars.secret.secret
}]
